-- Official-source verified expansion: AI learning and teaching tools.

insert into public.tools (
 name,description,full_description,url,logo_url,pricing_type,pricing_start_at,pricing_summary,pricing_details,pricing_currency,pricing_url,pricing_verified_at,
 korean_support_level,is_verified,source_verified,hands_on_verified,api_tested,korean_tested,verification_level,verification_notes,
 is_domestic,has_api,api_url,ai_type,tool_scope,primary_features,secondary_features,key_benefits,best_for,limitations,verification_sources,verified_at,updated_at
)
select * from (values
('Duolingo','게임형 학습과 AI 영상 통화·역할극으로 외국어를 연습하는 학습 앱 #외국어 #AI회화 #교육 #모바일앱','Duolingo는 40개 이상 언어의 짧은 게임형 수업을 무료로 제공하고, Max 구독에서 AI 캐릭터 영상 통화와 역할극, 개인화된 문법 설명을 결합한 언어 학습 플랫폼입니다.','https://www.duolingo.com/learn','https://www.duolingo.com/favicon.ico','Freemium','$0','기본 과정 무료 · Max 가격은 국가·플랫폼별 표시',array['언어 과정과 기본 학습 기능은 무료입니다.','Super는 광고 제거·무제한 하트·추가 연습을 제공하고 Max는 AI 영상 통화와 역할극을 추가합니다.','구독 가격은 국가, 결제 플랫폼, 개인·가족 플랜에 따라 달라 공식 고정 금액을 표시하지 않습니다.'],'USD','https://www.duolingo.com/learn',now(),'Full Support',true,true,false,false,false,'official_sources','공식 학습·Max 소개에서 한국어 과정과 AI 기능을 확인했습니다. 한국어 UI·회화 품질과 결제 가격은 직접 테스트하지 않았습니다.',false,false,null,'Augmented','general',array['게임형 언어 수업','AI 영상 통화','AI 역할극·피드백'],array['개인화 복습','문법 설명','학습 연속 기록·리그'],array['무료 핵심 언어 과정','짧은 반복 학습','AI 캐릭터와 회화 연습'],array['매일 짧게 외국어를 연습하는 학습자','한국어를 포함한 입문 언어 과정을 찾는 사용자'],array['Max AI 기능은 학습 언어와 지역에 따라 제공 범위가 다릅니다.','실전 회화를 완전히 대체하지 않으며 AI 답변에 오류가 있을 수 있습니다.','정확한 구독료는 앱 내 결제 화면에서 확인해야 합니다.'],array['https://www.duolingo.com/learn','https://blog.duolingo.com/duolingo-max/','https://blog.duolingo.com/duolingo-101-how-to-learn-a-language-on-duolingo/'],now(),now()),
('Photomath','수학 문제를 카메라로 인식해 풀이 과정과 설명을 보여주는 AI 학습 앱 #수학 #문제풀이 #교육 #카메라인식','Photomath는 인쇄·필기 수학 문제를 촬영하거나 입력하면 산술부터 미적분·기하·문장제까지 단계별 풀이를 제공하고, Plus에서 애니메이션 설명과 심화 해설을 추가합니다.','https://photomath.com/','https://photomath.com/favicon.ico','Freemium','$0','기본 단계별 풀이 무료 · Plus 앱 내 지역별 가격',array['앱 다운로드와 기본 단계별 풀이 설명은 무료입니다.','Photomath Plus는 애니메이션 튜토리얼, 교사 검토 정의와 단계별 심화 설명을 제공합니다.','Plus는 Google Play·App Store에서 판매되며 가격과 무료 체험은 지역과 시점에 따라 달라집니다.'],'USD','https://photomath.com/',now(),'Partial Support',true,true,false,false,false,'official_sources','공식 제품 소개와 이용약관에서 무료·Plus 기능을 확인했습니다. 한국어 설명 품질, 문제 인식과 앱스토어 가격은 직접 테스트하지 않았습니다.',false,false,null,'Augmented','specialized',array['카메라 수학 문제 인식','단계별 풀이','수학 개념 설명'],array['애니메이션 튜토리얼','계산기 입력','문장제·기하 지원'],array['답과 풀이 과정을 함께 확인','필기·인쇄 문제 촬영','산술부터 미적분까지 폭넓은 범위'],array['풀이 과정을 확인하려는 학생과 학부모','수학 숙제를 복습하는 학습자'],array['앱이 제시한 풀이를 그대로 제출하면 학습과 학업윤리에 문제가 생길 수 있습니다.','복잡한 필기·도형 인식은 입력 품질에 영향을 받습니다.','Plus 가격은 앱스토어에서 별도로 확인해야 합니다.'],array['https://www.photomath.com/articles/photomath-101-get-math-with-photomath/','https://photomath.com/terms/'],now(),now()),
('MagicSchool','교사와 학생을 위한 수업계획·퀴즈·피드백 AI 도구 모음 #교사 #수업자료 #교육 #AI챗봇','MagicSchool은 수업 계획, 워크시트, 퀴즈, 개별화 교육계획과 글쓰기 피드백을 생성하고 학생용 AI 활동 공간과 학교 관리자 통제를 제공하는 교육 전용 AI 플랫폼입니다.','https://www.magicschool.ai/','https://www.magicschool.ai/favicon.ico','Freemium','$0','무료 플랜 · Plus 연간 월 환산 $8.33',array['Free는 교사용 80개 이상, 학생용 50개 이상 도구와 Raina 챗봇을 제공합니다.','Plus는 연간 결제 시 사용자당 월 $8.33, 월 결제 시 $12.99입니다.','학교·교육청 Enterprise는 LMS·SSO·관리·보안 기능을 포함하는 맞춤 견적입니다.'],'USD','https://www.magicschool.ai/pricing',now(),'Partial Support',true,true,false,false,false,'official_sources','공식 가격·기능·보안 정보를 확인했습니다. 한국어 생성 품질과 학생 보호 기능은 직접 테스트하지 않았습니다.',false,false,null,'Native','specialized',array['수업계획·자료 생성','퀴즈·평가 생성','학생 글쓰기 피드백'],array['학생용 AI Room','Raina 챗봇','LMS·학교 관리자 통제'],array['교사 업무를 한 플랫폼에서 지원','무료 교육 도구 다수 제공','학생용 가드레일과 관리 기능'],array['수업 자료 제작 시간을 줄이려는 교사','학교 단위로 생성형 AI를 관리하려는 교육기관'],array['생성된 수업 내용과 평가 문항은 교사가 검토해야 합니다.','한국 교육과정 정렬은 별도 설정과 검증이 필요합니다.','SSO·LMS와 고급 관리 기능은 Enterprise 계약이 필요합니다.'],array['https://www.magicschool.ai/pricing'],now(),now()),
('Brisk Teaching','문서·슬라이드·영상 안에서 수업자료와 피드백을 만드는 교사용 AI #교사 #수업자료 #피드백 #브라우저확장','Brisk Teaching은 Chrome·Edge 확장과 웹에서 문서, 슬라이드, 웹페이지와 YouTube를 읽어 수업계획·퀴즈·루브릭·피드백을 만들고 학생용 Brisk Boost 활동을 제공하는 교육 AI입니다.','https://www.briskteaching.com/','https://www.briskteaching.com/favicon.ico','Freemium','$0','교사용 무료 플랜 · 학교·교육청 맞춤 견적',array['Educator Free는 월 $0으로 20개 이상 핵심 AI 도구를 계속 제공합니다.','가입 후 14일 동안 학교용 Premium 기능을 체험하고 이후 무료 플랜으로 전환됩니다.','학교·교육청 Premium과 Intelligence는 학생 수와 계정 범위에 따른 맞춤 견적입니다.'],'USD','https://www.briskteaching.com/plans',now(),'Partial Support',true,true,false,false,false,'official_sources','공식 플랜·FAQ에서 무료 범위와 50개 이상 언어 자료 생성을 확인했습니다. 한국어 출력과 브라우저 확장은 직접 테스트하지 않았습니다.',false,false,null,'Augmented','specialized',array['수업계획·퀴즈 생성','루브릭·글쓰기 피드백','읽기 수준 변환'],array['Brisk Boost 학생 활동','문서·슬라이드·영상 연동','학교용 분석·관리'],array['기존 교사 작업 화면에서 바로 사용','20개 이상 도구 무료','다국어 수업자료 생성'],array['Google 문서와 LMS를 사용하는 교사','학교 단위 AI 수업 도구를 도입하는 기관'],array['한국어 생성은 공식 다국어 범위에 포함될 수 있으나 직접 품질 검증이 필요합니다.','무료와 학교용 플랜의 도구·사용량 범위가 다릅니다.','학생 자료 입력 전 학교 개인정보 정책을 확인해야 합니다.'],array['https://www.briskteaching.com/faq','https://www.briskteaching.com/plans'],now(),now()),
('Wolfram|Alpha','자연어 질문을 계산 가능한 지식과 알고리즘으로 분석하는 계산 지식 엔진 #수학 #과학 #계산 #교육','Wolfram|Alpha는 자연어·수식 입력을 정제된 지식 데이터와 계산 알고리즘으로 처리해 수학·과학·공학·통계 등의 답과 시각화를 만들며 Pro에서 단계별 풀이와 연습 문제를 제공합니다.','https://www.wolframalpha.com/','https://www.wolframalpha.com/favicon.ico','Freemium','$0','Basic 무료 · Pro 연간 월 환산 $5',array['로그인 기반 Basic은 무료이며 단계별 풀이는 포함하지 않습니다.','Pro는 연간 $60으로 월 환산 $5, 월 결제는 $9.99입니다.','Pro Premium은 연간 $99으로 월 환산 $8.25, 월 결제는 $12입니다.'],'USD','https://www.wolframalpha.com/pro/pricing/',now(),'Partial Support',true,true,false,false,false,'official_sources','공식 제품·가격 페이지에서 계산 분야, Pro 기능과 API 제공을 확인했습니다. 한국어 자연어 입력과 API는 직접 테스트하지 않았습니다.',false,true,'https://products.wolframalpha.com/api/','Native','general',array['자연어 계산 질의','수학·과학 지식 계산','단계별 풀이'],array['연습 문제·힌트','파일·사진 입력','그래프·결과 다운로드'],array['정제된 데이터 기반 계산','광범위한 전문 지식 영역','개발자 API 제공'],array['수학·과학 풀이를 확인하는 학습자','정확한 계산 결과가 필요한 연구·업무 사용자'],array['무료 Basic에는 단계별 풀이가 없습니다.','한국어 자연어 질문의 해석 품질은 직접 확인이 필요합니다.','계산 결과도 입력 조건과 출처를 검토해야 합니다.'],array['https://www.wolframalpha.com/','https://www.wolframalpha.com/pro/pricing/'],now(),now())
) as seed(name,description,full_description,url,logo_url,pricing_type,pricing_start_at,pricing_summary,pricing_details,pricing_currency,pricing_url,pricing_verified_at,korean_support_level,is_verified,source_verified,hands_on_verified,api_tested,korean_tested,verification_level,verification_notes,is_domestic,has_api,api_url,ai_type,tool_scope,primary_features,secondary_features,key_benefits,best_for,limitations,verification_sources,verified_at,updated_at)
where not exists(select 1 from public.tools where lower(tools.url)=lower(seed.url));

with assignments(tool_url,category_slug) as (values
('https://www.duolingo.com/learn','education'),('https://www.duolingo.com/learn','productivity'),
('https://photomath.com/','education'),('https://photomath.com/','search-data'),
('https://www.magicschool.ai/','education'),('https://www.magicschool.ai/','productivity'),
('https://www.briskteaching.com/','education'),('https://www.briskteaching.com/','productivity'),
('https://www.wolframalpha.com/','education'),('https://www.wolframalpha.com/','search-data')
)
insert into public.tool_categories(tool_id,category_id)
select tools.id,categories.id from assignments
join public.tools on lower(tools.url)=lower(assignments.tool_url)
join public.categories on lower(categories.slug)=lower(assignments.category_slug)
on conflict(tool_id,category_id) do nothing;
